pub fn count_digits(text: &Vec<char>) -> usize {
    // Count characters whose ASCII code is between '0' and '9' inclusive.
    text.iter()
        .filter(|&&c| c.is_ascii() && ('0'..='9').contains(&c))
        .count()
}